package com.jnapanam.sportszone.booking.service;
import com.jnapanam.sportszone.booking.dto.BookingResponse;import com.jnapanam.sportszone.booking.model.*;import com.jnapanam.sportszone.booking.repository.*;import com.jnapanam.sportszone.common.exception.*;import java.math.*;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class BookingRescheduleService{private final BookingRepository bookings;private final BookingSlotRepository slots;private final JdbcTemplate jdbc;public BookingRescheduleService(BookingRepository b,BookingSlotRepository s,JdbcTemplate j){bookings=b;slots=s;jdbc=j;}
 @Transactional public Map<String,Object> reschedule(UUID actor,UUID bookingId,UUID newSlotId,boolean staff){Booking b=bookings.findById(bookingId).orElseThrow(()->new NotFoundException("Booking not found"));if(!staff&&!b.getUser().getId().equals(actor))throw new NotFoundException("Booking not found");if(b.getStatus()!=BookingStatus.CONFIRMED&&b.getStatus()!=BookingStatus.PENDING_PAYMENT)throw new ConflictException("Booking cannot be rescheduled");if(b.getCheckedInAt()!=null)throw new ConflictException("Checked-in bookings cannot be rescheduled");if(b.getSlot().getId().equals(newSlotId))throw new ConflictException("Choose a different slot");BookingSlot old=slots.findLocked(b.getSlot().getId()).orElseThrow();BookingSlot target=slots.findLocked(newSlotId).orElseThrow(()->new NotFoundException("New slot not found"));if(!target.getFacility().isAvailableOn(target.getDate()))throw new ConflictException("Target facility is unavailable on that date");if(!LocalDateTime.of(target.getDate(),target.getStartTime()).isAfter(LocalDateTime.now()))throw new ConflictException("New slot must be in the future");if(!target.getFacility().getSport().getId().equals(old.getFacility().getSport().getId()))throw new ConflictException("Reschedule must remain within the same sport");if(target.available()<b.getQuantity())throw new ConflictException("Requested capacity is no longer available");BigDecimal oldPrice=old.getFacility().getBookingPrice().multiply(BigDecimal.valueOf(b.getQuantity()));BigDecimal newPrice=target.getFacility().getBookingPrice().multiply(BigDecimal.valueOf(b.getQuantity()));old.cancel(b.getQuantity());target.hold(b.getQuantity());target.confirm(b.getQuantity());b.reschedule(target);BigDecimal diff=newPrice.subtract(oldPrice);long diffPaise=diff.movePointRight(2).longValue();String adjustment=diffPaise>0?"PAYMENT_DUE":diffPaise<0?"REFUND_DUE":"NOT_REQUIRED";jdbc.update("insert into booking_reschedules(id,booking_id,old_slot_id,new_slot_id,changed_by,price_difference_paise,adjustment_status) values(?,?,?,?,?,?,?)",UUID.randomUUID(),b.getId(),old.getId(),target.getId(),actor,diffPaise,adjustment);return Map.of("booking",BookingResponse.from(b),"oldPrice",oldPrice,"newPrice",newPrice,"priceDifference",diff,"adjustmentStatus",adjustment);}}
